/**
 * attribution.test.ts — AI attribution must never enter this repo.
 *
 * Fixtures here intentionally contain the forbidden phrases; this file is on
 * the guard's allowlist (see scripts/check-attribution.ts).
 */

import { describe, expect, test } from "bun:test";
import { containsAiAttribution, stripAiAttribution } from "../src/lib/attribution";

describe("containsAiAttribution", () => {
  const bad = [
    "_Generated by [Claude Code](https://claude.ai/code)_",
    "Generated with Claude Code",
    "🤖 Generated with [Claude Code](https://claude.com/claude-code)",
    "Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>",
    "co-authored-by: GitHub Copilot <copilot@github.com>",
    "Claude-Session: https://claude.ai/code/session_abc",
    "Generated by ChatGPT",
    "_Generated by Claude Code_",
    "*Generated with Codex*",
    "see https://claude.ai/code/session_x",
  ];
  for (const s of bad) test(`flags: ${s}`, () => expect(containsAiAttribution(s)).toBe(true));

  const ok = [
    "Add a Claude adapter to the harness registry",
    "The claude-code harness runs agents",
    "Generated files are checked in CI",
    "generated by the docs generator",
    "Co-authored-by: Alice Example <alice@example.com>",
  ];
  for (const s of ok) test(`allows: ${s}`, () => expect(containsAiAttribution(s)).toBe(false));
});

describe("stripAiAttribution", () => {
  test("removes a trailing footer and its separator", () => {
    const body = "Real content.\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_\n";
    expect(stripAiAttribution(body)).toBe("Real content.");
  });
  test("removes commit-style trailers", () => {
    const msg = "fix: thing\n\nbody\n\nCo-Authored-By: Claude <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/s\n";
    expect(stripAiAttribution(msg)).toBe("fix: thing\n\nbody");
  });
  test("leaves ordinary text and horizontal rules untouched", () => {
    const body = "Intro\n\n---\n\nSecond part about Claude adapters";
    expect(stripAiAttribution(body)).toBe(body);
  });
  test("is idempotent", () => {
    const once = stripAiAttribution("x\n\n---\n_Generated by Claude Code_");
    expect(stripAiAttribution(once)).toBe(once);
  });
});
